@Component("registration-handler")
@ProcessingGroup("registration-processing-group")
public class RegistrationEventHandler {
	
	// core constructor
	RegistrationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateRegistrationEvent
     */
    @EventHandler
    public void handle( CreateRegistrationEvent event) {
        entityManager.persist(new Registration(event.getRegistrationId(), event.getTailNumber(), event.getRegistryCountry(), event.getAircraft()));
    }

    /*
     * @param	event UpdateRegistrationEvent
     */
    @EventHandler
    public Registration handle( UpdateRegistrationEvent event) {
    	entityManager.merge(new Registration(event.getRegistrationId(), event.getTailNumber(), event.getRegistryCountry(), event.getAircraft()));
    }
    
    /*
     * @param	event DeleteRegistrationEvent
     */
    @EventHandler
    public void on( DeleteRegistrationEvent event) {
    	Registration entity = new Registration();
   
    	// ------------------------------------------
    	// apply the RegistrationId
    	// ------------------------------------------
    	entity.setRegistrationId( event.getRegistrationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final RegistrationRepository registrationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(RegistrationEventHandler.class.getName());

}
